package companion

// The log workbench follows New API's compact filter toolbar, inline statistics,
// dense data table, responsive cards, and per-request detail view.
const usageLogScript = `<script>
window.__companionRegister('logs', signal => {
const advancedToggle = document.querySelector('.log-more');
if (advancedToggle) advancedToggle.addEventListener('toggle', () => {
  document.querySelector('[data-advanced-filters]').hidden = !advancedToggle.open;
}, {signal});
document.querySelectorAll('[data-log-detail]').forEach(button => button.addEventListener('click', () => {
  document.getElementById(button.dataset.logDetail)?.showModal();
}, {signal}));
document.querySelectorAll('[data-close-dialog]').forEach(button => button.addEventListener('click', () => {
  button.closest('dialog')?.close();
}, {signal}));
document.querySelectorAll('.log-dialog').forEach(dialog => dialog.addEventListener('click', event => {
  if (event.target === dialog) dialog.close();
}, {signal}));
document.querySelectorAll('[data-column-toggle]').forEach(input => input.addEventListener('change', () => {
  document.querySelectorAll('[data-col="' + input.dataset.columnToggle + '"]').forEach(cell => { cell.hidden = !input.checked; });
}, {signal}));
const exportButton = document.querySelector('[data-export-page]');
if (exportButton) exportButton.addEventListener('click', () => {
  const rows = [...document.querySelectorAll('.logs-table tr')].map(row =>
    [...row.querySelectorAll('th,td')].filter(cell => !cell.hidden && cell.dataset.col !== 'detail')
      .map(cell => '"' + cell.innerText.replaceAll('"', '""').replaceAll(String.fromCharCode(10), ' ') + '"').join(','));
  const blob = new Blob([String.fromCharCode(0xfeff) + rows.join(String.fromCharCode(13,10))], {type:'text/csv;charset=utf-8'});
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = 'cpa-usage-logs-page.csv';
  link.click();
  setTimeout(() => URL.revokeObjectURL(link.href), 1000);
}, {signal});
});
</script>`

const usageLogDetailTemplate = `<dialog class="log-dialog" id="log-detail-{{.ID}}"><div class="log-dialog-head"><div><h2>请求详情</h2><p>日志 #{{.ID}} · {{.AtText}} · 北京时间</p></div><button class="log-dialog-close" type="button" data-close-dialog aria-label="关闭">×</button></div><div class="log-dialog-body"><section class="log-detail-section"><h3>请求</h3><dl><div><dt>状态</dt><dd>{{.Status}} · {{if .Successful}}成功{{else}}失败{{end}}</dd></div>{{if not .Successful}}<div><dt>错误码</dt><dd>{{.ErrorCodeText}}</dd></div><div><dt>错误消息</dt><dd>{{if .ErrorMessage}}{{.ErrorMessage}}{{else}}未记录{{end}}</dd></div>{{end}}<div><dt>模型</dt><dd>{{if .Model}}{{.Model}}{{else}}—{{end}}</dd></div><div><dt>路径</dt><dd>{{.Route}}</dd></div><div><dt>耗时</dt><dd class="log-duration-pair"><span>首字 <b>{{.FirstByteText}}</b></span><span>总耗时 <b>{{.DurationMS}} ms</b></span></dd></div></dl></section><section class="log-detail-section"><h3>路由</h3><dl><div><dt>用户名 / ID</dt><dd>{{.Username}} · {{.UserID}}</dd></div><div><dt>API Key ID</dt><dd>{{if .KeyID}}{{.KeyID}}{{else}}—{{end}}</dd></div><div><dt>方案 ID</dt><dd>{{if .PlanID}}{{.PlanID}}{{else}}—{{end}}</dd></div><div><dt>账号前缀</dt><dd>{{if .AccountPrefix}}{{.AccountPrefix}}{{else}}—{{end}}</dd></div></dl></section><section class="log-detail-section"><h3>用量与费用</h3><dl><div><dt>输入 Token</dt><dd>{{.InputTokens}}</dd></div><div><dt>输出 Token</dt><dd>{{.OutputTokens}}</dd></div><div><dt>缓存命中率</dt><dd>{{.CacheHitRateText}}</dd></div><div><dt>缓存读取</dt><dd>{{.CacheReadTokens}}</dd></div><div><dt>缓存写入</dt><dd>{{.CacheWriteTokens}}</dd></div><div><dt>费用 · USD</dt><dd class="cost">${{.CostUSD}}{{if .Estimated}} · 估算{{end}}</dd></div></dl></section></div></dialog>`

const usageLogsTemplate = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>使用日志 · CPA Companion</title>` + stylesheetLink + `</head><body><div class="shell"><aside class="sidebar"><a class="brand" href="/dashboard"><img class="brand-mark" src="/assets/logo.png" width="30" height="30" alt=""><span class="brand-copy"><span class="brand-title">CPA Companion</span>` + brandVersionTemplate + `</span></a><nav class="nav"><span class="nav-label">工作台</span><a class="nav-link" href="/dashboard">仪表盘</a><a class="nav-link" href="/keys">我的密钥</a>{{if .Admin}}<a class="nav-link" href="/admin">分流方案</a><a class="nav-link" href="/audit">内容审计</a>{{end}}<a class="nav-link" href="/prices">模型价格</a><a class="nav-link active" aria-current="page" href="/logs">使用日志</a></nav>` + sidebarGitHubTemplate + `<div class="sidebar-footer"><div class="identity"><span class="avatar"><span class="avatar-fallback">C</span>{{if .User.AvatarURL}}<img src="{{.User.AvatarURL}}" alt="" referrerpolicy="no-referrer">{{end}}</span><span class="identity-copy"><span class="identity-name">{{.User.Username}}</span><span class="identity-meta">{{.User.ID}}</span></span></div><form method="post" action="/auth/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="logout">退出登录</button></form></div></aside><main class="content"><div class="log-workbench">
<header class="log-head"><div><h1>使用日志</h1><p>按请求查看模型、Token、费用和上游路由 · 北京时间</p></div>{{if .Admin}}<nav class="log-scope" aria-label="日志范围"><a href="{{.AllURL}}" class="{{if .All}}active{{end}}">全部用户</a><a href="{{.SelfURL}}" class="{{if not .All}}active{{end}}">仅看自己</a></nav>{{end}}</header>
<form class="log-toolbar" action="/logs" method="get">{{if .Admin}}<input type="hidden" name="scope" value="{{if .All}}all{{else}}self{{end}}">{{end}}<div class="log-filter-grid"><label class="log-field log-date-field"><span>时间范围 · 北京时间</span><span class="log-date-pair"><input type="datetime-local" name="start" value="{{.Start}}" aria-label="开始时间"><span>—</span><input type="datetime-local" name="end" value="{{.End}}" aria-label="结束时间"></span></label><label class="log-field"><span>模型</span><input name="model" value="{{.Model}}" placeholder="模型名称" autocomplete="off"></label><label class="log-field"><span>类型</span><select name="status" aria-label="请求类型"><option value="" {{if not .Status}}selected{{end}}>全部请求</option><option value="success" {{if eq .Status "success"}}selected{{end}}>成功</option><option value="error" {{if eq .Status "error"}}selected{{end}}>失败</option></select></label><details class="log-more" {{if or .UserFilter .KeyID .AccountID .Route}}open{{end}}><summary>更多筛选</summary></details></div><div class="log-advanced" data-advanced-filters {{if not (or .UserFilter .KeyID .AccountID .Route)}}hidden{{end}}>{{if and .Admin .All}}<label class="log-field"><span>用户 ID</span><input name="user" value="{{.UserFilter}}" placeholder="精确用户 ID" autocomplete="off"></label>{{end}}<label class="log-field"><span>API Key ID</span><input name="key" value="{{.KeyID}}" placeholder="精确密钥 ID" autocomplete="off"></label><label class="log-field"><span>上游账号 ID</span><input name="account" value="{{.AccountID}}" placeholder="精确账号 ID" autocomplete="off"></label><label class="log-field"><span>请求路径</span><input name="route" value="{{.Route}}" placeholder="例如 /v1/chat/completions" autocomplete="off"></label></div><div class="log-toolbar-bottom"><div class="log-stats" aria-label="当前筛选统计"><span class="log-stat"><span>费用</span><b>${{.Summary.CostUSD}}</b></span><span class="log-stat rose"><span>RPM</span><b>{{.Minute.Requests}}</b></span><span class="log-stat slate"><span>TPM</span><b>{{.Minute.TotalTokens}}</b></span></div><div class="log-actions"><a class="log-btn" href="{{.ResetURL}}">重置</a><button class="log-btn primary" type="submit">查询</button><button class="log-btn" type="button" data-export-page {{if not .Rows}}disabled{{end}}>导出本页</button><details class="log-column-menu"><summary class="log-btn" role="button">列设置 ▾</summary><div class="log-column-popover"><label><input type="checkbox" data-column-toggle="key" checked>API Key</label><label><input type="checkbox" data-column-toggle="account" checked>上游账号</label><label><input type="checkbox" data-column-toggle="tokens" checked>Token</label><label><input type="checkbox" data-column-toggle="cache-rate" checked>缓存命中率</label><label><input type="checkbox" data-column-toggle="cost" checked>费用</label><label><input type="checkbox" data-column-toggle="duration" checked>耗时</label></div></details></div></div></form>
{{if .LogID}}<p class="log-note">正在查看审计关联的请求日志 #{{.LogID}} · <a href="{{.ResetURL}}">返回全部日志</a></p>{{end}}<section class="log-table-shell"><div class="log-table-top"><strong>请求记录</strong><span>共 {{.Summary.Requests}} 条 · 每页最多 50 条</span></div>{{if .Rows}}<div class="log-table-scroll"><table class="logs-table"><thead><tr><th data-col="time">时间 / 状态</th>{{if .Admin}}<th data-col="user">用户名</th>{{end}}<th data-col="key">API Key</th><th data-col="model">模型 / 路径</th><th data-col="account">上游账号</th><th data-col="tokens">Token 输入 / 输出</th><th data-col="cache-rate">缓存命中率</th><th data-col="cost">费用</th><th data-col="duration">耗时</th><th data-col="detail">详情</th></tr></thead><tbody>{{range .Rows}}<tr><td data-col="time"><span class="log-date">{{.AtText}}</span><span class="log-type {{if not .Successful}}error{{end}}">{{if .Successful}}成功{{else}}失败 · {{.Status}}{{end}}</span></td>{{if $.Admin}}<td data-col="user"><span class="log-username">{{.Username}}</span></td>{{end}}<td data-col="key"><span class="log-code">{{if .KeyID}}{{.KeyID}}{{else}}—{{end}}</span></td><td data-col="model"><span class="log-model" title="{{.Model}}">{{if .Model}}{{.Model}}{{else}}—{{end}}</span><span class="log-sub" title="{{.Route}}">{{.Route}}</span></td><td data-col="account"><span class="log-code">{{if .AccountPrefix}}{{.AccountPrefix}}{{else}}—{{end}}</span></td><td data-col="tokens"><span class="log-token">{{.InputTokens}} / {{.OutputTokens}}</span>{{if or .CacheReadTokens .CacheWriteTokens}}<span class="log-sub">缓存 ↓{{.CacheReadTokens}} · ↑{{.CacheWriteTokens}}</span>{{end}}</td><td data-col="cache-rate"><span class="log-cache-rate">{{.CacheHitRateText}}</span></td><td data-col="cost"><span class="log-cost">${{.CostUSD}}</span>{{if .Estimated}}<span class="log-estimated">估算</span>{{end}}</td><td data-col="duration"><span class="log-time-metric"><span>首字 </span><b>{{.FirstByteText}}</b></span><span class="log-time-metric"><span>总耗时 </span><b>{{.DurationMS}} ms</b></span></td><td data-col="detail"><button type="button" class="log-detail-btn" data-log-detail="log-detail-{{.ID}}">查看</button></td></tr>{{end}}</tbody></table></div><div class="log-mobile-list">{{range .Rows}}<article class="log-mobile-card"><div class="log-mobile-top"><span class="log-model">{{if .Model}}{{.Model}}{{else}}—{{end}}</span><span class="log-cost">${{.CostUSD}}</span></div><div class="log-mobile-meta"><span><span class="log-type {{if not .Successful}}error{{end}}">{{if .Successful}}成功{{else}}失败 · {{.Status}}{{end}}</span><br>{{.AtText}}</span><span>{{.InputTokens}} / {{.OutputTokens}} Token<br>缓存命中率 {{.CacheHitRateText}}<br>首字 {{.FirstByteText}} · 总耗时 {{.DurationMS}} ms</span></div><div class="log-mobile-bottom"><span class="log-code">{{if $.Admin}}{{.Username}} · {{end}}{{if .AccountPrefix}}{{.AccountPrefix}}{{else}}—{{end}}</span><button type="button" class="log-detail-btn" data-log-detail="log-detail-{{.ID}}">查看详情</button></div></article>{{end}}</div>{{else}}<div class="log-empty"><div><strong>暂无使用日志</strong><div>调整筛选条件，或通过 API Key 发起请求后再查看。</div></div></div>{{end}}<div class="log-pagination">{{if .HasPrevious}}<a href="{{.PreviousURL}}">‹ 上一页</a>{{end}}<span>第 {{.Page}} / {{if .TotalPages}}{{.TotalPages}}{{else}}1{{end}} 页</span>{{if .HasNext}}<a href="{{.NextURL}}">下一页 ›</a>{{end}}</div></section>
{{range .Rows}}` + usageLogDetailTemplate + `{{end}}<p class="log-note">仅保存请求元数据及失败响应的错误码、错误消息，不保存请求正文、完整响应正文或 API Key 明文。费用按请求完成时的模型价格记录。</p>
</div></main></div>` + moduleBootstrapScript + selectControlScript + usageLogScript + navigationScript + `</body></html>`
